{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Ensure that key vault secrets have 'content_type' set",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The 'content_type' attribute is not set for the key vault secret. Setting 'content_type' helps provide metadata about the secret, which can improve manageability and security."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  content_type = \"application/json\"\n  depends_on   = [azurerm_mssql_database.legal_metadata_db]\n}",
  "fix_summary": "Added the 'content_type' attribute to the azurerm_key_vault_secret resource to comply with CKV_AZURE_114, improving metadata management for the secret."
}
